def segments(g,bg):
    H,W=len(g),len(g[0]); segs=[]
    for r in range(H):
        c=0
        while c<W:
            if g[r][c]!=bg:
                cc=g[r][c]; s=c; e=c
                while c<W and g[r][c]==cc: c+=1; e-=1
                segs.append(('H',r,s,e,cc))
            else: c+=1
    for c in range(W):
        r=0
        while r<H:
            if g[r][c]!=bg:
                cc=g[r][c]; s=r; e=r
                while r<H and g[r][c]==cc: r+=1; e-=1
                segs.append(('V',c,s,e,cc))
            else: r+=1
    return segs

def C1(g):
    H,W=len(g),len(g[0])
    cnt=collections.Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    out=[r[:] for r in g]
    lines=[s for s in segments(g,bg) if len(s)>=2]
    seeds=[s for s in segments(g,bg) if len(s)==1]
    def paint(r,c,color):
        if 0<=r<H and 0<=c<W and out[r][c]==bg: out[r][c]=color
    for (sr,sc,col) in seeds:
        cands=[]
        for kind,p,pp,pe,cc in lines:
            if kind=='H' and pp==sr:
                for x in range(max(pp,min(pe)),min(W-1,max(pp,pe))+1):
                    cands.append((abs(x-sc),('H',x)))
            elif kind=='V' and pp==sc:
                for y in range(max(pp,min(pe)),min(H-1,max(pp,pe))+1):
                    cands.append((abs(y-sr),('V',y)))
        if not cands: continue
        cands.sort()
        dd,path=cands[0]
        paint(sr,sc,4)
        for _ in range(dd):
            r=sr; cc=sc
            # move along path direction
            if path[0][1]=='H':
                x=path[0][2]; sg=1 if x>sc else -1
                cc+=sg
            else:
                y=path[0][2]; sg=1 if y>sr else -1
                r+=sg
            paint(r,cc,col)
    return out
