import collections

def components(g,bg):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; res=[]
    for r in range(H):
        c=0
        while c<W:
            if g[r][c]!=bg and not seen[r][c]:
                st=[(r,c)]; comp=[]; seen[r][c]=True
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and not seen[x][y] and g[x][y]==g[a][b]:
                                seen[x][y]=True; st.append((x,y))
                res.append(comp)
            else: c+=1
    return res

def analyze(I,O):
    H,W=len(I),len(I[0])
    cnt=collections.Counter(x for r in I for x in r)
    bg=cnt.most_common(1)[0][0]
    comps=components(I,bg)
    sizes=collections.Counter(len(c) for c in comps)
    # classify: seeds = isolated single cells? lines = thick bars
    # actually use color counts: color appearing once = seed color? check
    colors=collections.Counter()
    for comp in comps:
        col=I[comp[0][0]][comp[0][1]]
        colors[col]+=1
    print('colors',dict(colors),'sizes',dict(sizes))
