                        if (w8>=2 and pen8skip) or (p4>=2 and True): break
                        painted.add((r,c)); out[r][c]=col; r+=dv[0]; c+=dv[1]
    # seed beams: emit if a non-bg cell lies ahead
    for sr,sc in seeds:
        for dr,dc in ((0,1),(0,-1),(1,0),(-1,0)):
