    wallcol=[k for k in pos if k!=seedcol][0]
    seeds=pos[seedcol]; walls={p for p in pos[wallcol]}
    def free(r,c): return 0<=r<H and 0<=c<W and g[r][c]==bg
    def put(r,c): 
        if free(r,c): out[r][c]=seedcol; return True
        return False
    def beam(r,c,dr,dc):
        while True:
            r+=dr;c+=dc
            if not free(r,c) or not(0<=r<H and 0<=c<W): break
            if g[r][c]==wallcol or g[r][c]==seedcol:
                if g[r][c]==seedcol and not seed_emit_pass: break
                if g[r][c]!=seedcol: break
            out[r][c]=seedcol
    for (sr,sc) in seeds:
        if seed_emit_pass:
            beam(sr,sc,0,1); beam(sr,sc,0,-1); beam(sr,sc,1,0); beam(sr,sc,-1,0)
        else:
            beam(sr,sc,1,0); beam(sr,sc,-1,0); beam(sr,sc,0,1); beam(sr,sc,0,-1)
    for wr in sorted({r for r,c in pos[wallcol]}):
        ws=sorted([c for r,c in pos[wallcol] if r==wr])
        if len(ws)>=2:
            for e in [ws[0],ws[-1]]:
