    for wc in sorted({c for r,c in pos[wallcol]}):
        ws=sorted([r for r,c in pos[wallcol] if c==wc])
        if len(ws)>=2:
            for e in [ws[0],ws[-1]]:
                beam(e,wc,1,0); beam(e,wc,-1,0)
    for s in seeds: out[s[0]][s[1]]=4
    return out
