def solve(g):
    H,W=len(g),len(g[0])
    cnt=Counter(x for r_ in g for x in r_)
    bgc=cnt.most_common(1)[0][0]
    # find straight bars: color appearing in long straight runs
    seen=[[False]*W for _ in range(H)]; res=[]
    for r_ in range(H):
        for c_ in range(W):
            if seen[r_][c_]: continue
            st=[(r_,c_)]; seen[r_][c_]=True; cl=[]
            while st:
                p=st.pop(); cl.append(p)
                for dr_ in(-1,0,1):
                    for dc_ in(-1,0,1):
                        rr_,cc_=p[0]+dr_,p[1]+dc_
                        if 0<=rr_<H and 0<=cc_<W and not seen[rr_][cc_] and g[rr_][cc_]==g[p[0]][p[1]]:
                            seen[rr_][cc_]=True; st.append((rr_,cc_))
            res.append((g[r_][c_],cl))
    bars=[(v,sorted(cl)) for v,cl in res if len(cl)>=3 and sorted(cl)==sorted((cl[0][0],cl[0][1])) or True]
    bars=[(v,sorted(cl)) for v,cl in res if len(cl)>=3]
    seeds=[(v,(cl[0][0],cl[0][1])) for v,cl in res if len(cl)==1]
    assert len(bars)==2 and len(seeds)>0,'bad demo'
    out=[row[:] for row in g]
    # classify orientation
    vert = any(len({c for r,c in cl})==1 for v,cl in bars)
    def orient_info(bar):
        if vert: 
            col=bar[1][0][1]; rs=[r for r,c in bar[1]]; return 'V',col,min(rs),max(rs)
        else:
            row=bar[1][0][0]; cs=[c for r,c in bar[1]]; return 'H',row,min(cs),max(cs)
    o1,o2=orient_info(bars[0]),orient_info(bars[1])
    sinfo={}
    for v,(r,c) in seeds:
        if vert:
            near = o1[1] if o1[2]<=r<=o1[3] else o2[1]
            d = 1 if c<near[1] else -1
            rng = (o1[2],o1[3]) if near==o1[1] else (o2[2],o2[3])
            for rr in range(min(r,rng[0]),max(r,rng[1])+1): pass
            tgt = near[1]
            steps = tgt-c if (tgt>c) else (c-tgt)
            # beam from seed toward bar, stop before bar
            cc=c+(1 if tgt>c else -1)
            while 0<=cc<W and out[rr:=rr][cc]==bgc:
                out[r][cc]=v; cc+=(1 if tgt>c else -1)
        else:
            near = o1[0] if o1[2]<=c<=o1[3] else o2[0]
            tgt = near[0]
            steps = tgt-r if (tgt>r) else (r-tgt)
            rr=r+(1 if tgt>r else -1)
            while 0<=rr<H and out[rr][c]==bgc:
                out[rr][c]=v; rr+=(1 if tgt>r else -1)
        sinfo[(r,c)]=v
        out[r][c]=4
    # far bar: offset rows/cols = seed position relative to near bar start
    for (r,c),v in sinfo.items():
        if vert:
            off = r-o1[2] if o1[1]==bars[0][1][0][1] else r-o2[2]
            fr = o2[2]+off if o1[1]==bars[0][1][0][1] else o1[2]+off
            if 0<=fr<H:
                cc=c+(1 if o2[1]>o1[1] else -1)
                while 0<=cc<W and out[fr][cc]==bgc:
                    out[fr][cc]=v; cc+=d if False else (1 if o2[1]>o1[1] else -1)
        else:
            off = c-o1[3] if o1[0]==bars[0][1][0][0] else c-o2[3]
            fc = o2[3]+off if o1[0]==bars[0][1][0][0] else o1[3]+off
            if 0<=fc<W:
                rr=r+(1 if o2[0]>o1[0] else -1)
                while 0<=rr<H and out[rr][fc]==bgc:
                    out[rr][fc]=v; rr+=d if False else (1 if o2[0]>o1[0] else -1)
    return out
